<?php require_once dirname(__DIR__).'/includes/auth.php';require_admin();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$s=db()->prepare('SELECT q.title,u.name,u.email,a.score,a.max_score,a.submitted_at FROM attempts a JOIN users u ON u.id=a.user_id JOIN quizzes q ON q.id=a.quiz_id WHERE a.quiz_id=? AND a.submitted_at IS NOT NULL ORDER BY a.submitted_at');$s->execute([$id]);$rows=$s->fetchAll();header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="resultados-qmax-quiz-'.$id.'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Quiz','Nome','E-mail','Pontos','Máximo','Data'],';');foreach($rows as $r)fputcsv($out,array_values($r),';');fclose($out);exit;

